effect.shader:
const int N = 9;
const float OFF[9] = float[9](-4.0,-3.0,-2.0,-1.0,0.0,1.0,2.0,3.0,4.0);
const float WT[9]  = float[9](0.028,0.070,0.133,0.196,0.228,0.196,0.133,0.070,0.028);
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

void main() {
    vec2 d = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = d * acTexelSize * (radius * acEscalaDePixel);
    float soma = 0.0;
    float pt = 0.0;
    for (int i = 0; i < N; i++) {
        vec2 u = acScreenNorm + passo * OFF[i];
        if (acPass == 0) {
            vec3 c = texture(inputImg, u).rgb;
            float l = dot(c, LUMA);
            soma += smoothstep(threshold, threshold + 0.1, l) * WT[i];
        } else {
            soma += texture(hblur, u).r * WT[i];
        }
        pt += WT[i];
    }
    float halo = soma / pt;
    if (acPass == 0) { fragColor = vec4(halo, 0.0, 0.0, 1.0); return; }
    vec4 orig = texture(inputImg, acScreenNorm);
    fragColor = vec4(orig.rgb + tint.rgb * tint.a * halo * intensity, orig.a);
}
